import{z as B,x as p,o as r,c as d,q as l,j as n,D as t,d as o,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"向量时钟","description":"","frontmatter":{"title":"向量时钟","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vector-clocks.md","filePath":"cs/vector-clocks.md","lastUpdated":1791063341000}'),A={name:"cs/vector-clocks.md"};function C(m,a,D,b,f,u){const E=p("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="向量时钟" tabindex="-1">向量时钟 <a class="header-anchor" href="#向量时钟" aria-label="Permalink to &quot;向量时钟&quot;">​</a></h1><div class="epigraph"><p>$a\\to b$ 当且仅当 $V(a)\\lt V(b)$。标量 Lamport 钟保存因果的「若」，向量钟把并发也标出来。</p><footer>—— 据 Lamport, Time, Clocks, and the Ordering of Events in a Distributed System, CACM 1978；Fidge, 1988；Mattern, 1989 整理</footer></div><p>上一课<a href="/cs/clock-drift">物理时钟</a>说明墙钟不能当因果。缺口是<strong>不靠准的物理时间，也能谈先后</strong>。本课先钉 happened-before 与 Lamport 标量钟，再补向量：并发不再被假全序抹平。后课 HLC 把物理时间嵌回这套偏序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lamport：\\(a\\to b\\)（happened-before）是最小传递关系，含同一进程内的程序顺序，以及「发消息先于对应收消息」。并发：\\(a\\nrightarrow b\\) 且 \\(b\\nrightarrow a\\)。标量逻辑钟 \\(C\\) 满足 \\(a\\to b\\Rightarrow C(a)\\lt C(b)\\)，逆命题不成立：钟大的不一定是因果后继，可能只是并发被编号排了队。</p><p>缺口：复制、调试、垃圾回收要问「这两次写是否并发」。标量钟回答不了。向量钟 \\(V\\) 是 \\(n\\) 维计数器，\\(V(a)\\lt V(b)\\)（逐分量 \\(\\le\\) 且至少一处 $\\lt $）当且仅当 \\(a\\to b\\)。</p><p><span class="marginnote">术语翻译：向量钟就是用「每人一个分量、各记各的计数」的手段来做「把并发从因果里挑出来」的事。直觉类比：标量钟像排队取号，谁号大谁在前——但排在前后不代表认识；向量钟像每人手里一份签到名单，名单 A 完全包含名单 B 才算「B 先于 A」，互有遗漏就是并列。</span></p><p><span class="marginnote">Fidge 与 Mattern 独立给出向量形式。Lamport 1978 的标量钟仍是发送时带时间戳、取 max 再加一的骨架。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每进程 \\(i\\) 维持 \\(V_i[1..n]\\)。本地事件：\\(V_i[i]\\) 加一。发送：带上当前向量。接收：逐分量取 max，再把 \\(V_i[i]\\) 加一。比较：不可比则并发。</p>',10)),(r(),n(i,null,{default:t(()=>[s(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20HB%5B%22happened-before%22%5D%20--%3E%20SC%5B%22%E6%A0%87%E9%87%8F%E9%92%9F%3A%20%E5%8D%95%E5%90%91%E8%95%B4%E5%90%AB%22%5D%0A%20%20HB%20--%3E%20VC%5B%22%E5%90%91%E9%87%8F%E9%92%9F%3A%20%E7%AD%89%E4%BB%B7%E5%88%BB%E7%94%BB%22%5D%0A%20%20VC%20--%3E%20CONC%5B%22%E4%B8%8D%E5%8F%AF%E6%AF%94%20%3D%20%E5%B9%B6%E5%8F%91%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"动态成员使 \\(n\\) 变化，向量要能增维或改用 interval tree clock 一类变体——本课点名，不展开。版本向量（version vector）常按副本而不是按进程索引，语义同构。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：三个进程 A、B、C。A 发消息前把向量写成 \\([3,0,0]\\)；B 收到后逐分量取 max 得 \\([3,1,0]\\)。若 C 独立走到 \\([0,2,4]\\)，与 \\([3,1,0]\\) 比较：C 不含 A 的 3、A 不含 C 的 4——两个向量不可比，这两条事件就是并发，而不是「C 的钟小所以更早」。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"因果广播、分布式断点、副本冲突检测都读「是否可比」。Dynamo 用版本向量标并发写，后课冲突再谈。本课不把 CRDT 的 payload 写进来：向量只给偏序，不合并不变量。",-1)),a[7]||(a[7]=e("p",null,"空间：\\(O(n)\\) 随进程数涨。这是精确刻画 happened-before 的代价；近似因果（如只保留最近 \\(k\\) 个）会漏并发。Plausible clocks、dotted version vectors 是压缩方向，后课若用到再点名。",-1)),a[8]||(a[8]=e("p",null,"与物理钟正交：向量不声称接近 UTC。同一进程内仍靠程序顺序，不靠 TSC。",-1)),a[9]||(a[9]=e("p",null,"调试时间线：把每个日志事件标向量，画成偏序图，比按墙钟排序少很多假边。这就是为什么追踪系统后来仍要带因果，而不是只带 NTP 时间戳。",-1)),(r(),n(i,null,{default:t(()=>[s(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20E1%5B%22A%3A%20%E6%9C%AC%E5%9C%B0%E4%BA%8B%E4%BB%B6%20x1%22%5D%20--%3E%20E2%5B%22A%3A%20%E5%8F%91%E9%80%81%20m%2C%20%E5%90%91%E9%87%8F%20%5B3%2C0%2C0%5D%22%5D%0A%20%20E2%20--%3E%20R1%5B%22B%3A%20%E6%94%B6%E5%88%B0%20m%2C%20%E9%80%90%E5%88%86%E9%87%8F%E5%8F%96%20max%22%5D%0A%20%20R1%20--%3E%20E3%5B%22B%3A%20%E6%9C%AC%E5%9C%B0%E4%BA%8B%E4%BB%B6%2C%20%5B3%2C1%2C0%5D%22%5D%0A%20%20E4%5B%22C%3A%20%E7%8B%AC%E7%AB%8B%E4%BA%8B%E4%BB%B6%2C%20%5B0%2C2%2C4%5D%22%5D%20--%3E%20CMP%7B%22%E4%B8%8E%20%5B3%2C1%2C0%5D%20%E6%AF%94%E8%BE%83%22%7D%0A%20%20E3%20--%3E%20CMP%0A%20%20CMP%20--%20%22%E9%80%90%E5%88%86%E9%87%8F%E5%9D%87%20%3C%3D%20%E4%B8%94%E8%87%B3%E5%B0%91%E4%B8%80%E5%A4%84%E5%88%86%E9%87%8F%E5%80%BC%E6%9B%B4%E5%B0%8F%E6%89%8D%E6%88%90%E7%AB%8B%22%20--%3E%20ORD%5B%22%E5%8F%AF%E6%AF%94%3A%20%E5%88%86%E5%87%BA%E5%85%88%E5%90%8E%22%5D%0A%20%20CMP%20--%20%22%E4%BA%92%E6%9C%89%E5%88%86%E9%87%8F%E5%AF%B9%E6%96%B9%E6%9B%B4%E5%B0%8F%22%20--%3E%20PAR%5B%22%E4%B8%8D%E5%8F%AF%E6%AF%94%3A%20%E5%88%A4%E5%B9%B6%E5%8F%91%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[10]||(a[10]=l('<p><span class="marginnote">常见误区：初学者容易以为向量钟要同步或对齐，实际上它不做任何等待——发送时原样捎带、接收时取 max 加一，一步不多。它量的不是「几点」，而是「谁的过去包含谁的过去」，所以与 NTP 的漂移毫无关系。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写混合逻辑钟，不定义全局快照。不把「向量时钟」当成数据库主键。后课默认：\\(a\\to b\\) 用向量比较；标量钟只用于需要任意全序扩展（如公平互斥的票据）的场合。物理误差 \\(\\varepsilon\\) 不再用来判定因果。</p><p>Lamport 全序扩展是把偏序拉成全序，用于需要单一顺序的算法；它<strong>制造</strong>顺序，不发现因果。向量拒绝制造。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>happened-before 是偏序；标量钟只保证单向蕴含。</li><li>向量钟与 \\(a\\to b\\) 等价；不可比即并发。</li><li>维数随参与者增长；压缩会牺牲完备。</li><li>出处：Lamport, CACM 1978；Fidge 1988；Mattern 1989。</li></ul>',6))])}const h=B(A,[["render",C]]);export{F as __pageData,h as default};
